140: export function createProject(workspace: string): Project {
141:   const sections = sectionDefinitions.map(([id, title, dependencies], index) => ({
142:     id,
143:     title,
144:     order: index + 1,
145:     dependencies: [...dependencies],
146:     content: "",
147:     version: 0,
148:     hash: contentHash(""),
149:     status: "NOT_STARTED" as const,
150:   }));
151:   return refreshNextAction(projectSchema.parse({
152:     schemaVersion: 1,
153:     id: randomUUID(),
154:     revision: 0,
155:     workspace,
156:     stage: "ORACLE",
157:     currentSectionId: sections[0].id,
158:     sections,
159:     approvals: [],
160:     actions: [],
161:     operations: [],
162:     evidence: [],
163:     nextAction: "Describe an idea and wake the Oracle",
164:     product: { status: "NONE", proposal: null, openQuestions: [] },
165:     makerScope: { status: "NONE", statement: null },
166:     transcript: [],
167:     capabilities: [
168:       {
169:         id: "inspect-changes",
170:         purpose: "Show the diff from the Maker's native session",
171:         nativeMapping: "OpenCode session.diff in the isolated demo workspace",
172:         availability: "unknown",
173:         permission: "Read-only inspection after a Maker run",
174:         observedOutcome: null,
175:       },
176:       {
177:         id: "node-check",
178:         purpose: "Run the approved dependency-free Node test",
179:         nativeMapping: "bounded node --test in the isolated demo workspace",
180:         availability: "available",
181:         permission: "Runs only after an explicit Maker scope grant and a native edit",
182:         observedOutcome: null,
183:       },
184:     ],
185:     witnessDrafts: [],
186:     nativeSessions: [],
187:   }));
188: }
