1: import { createNativeClient, FREE_DEEPSEEK_MODEL, type NativeClientOptions } from "../opencode/client.ts";
2: import {
3:   setOpenCodeResult,
4:   traceChatOperation,
5:   traceCreateAgent,
6:   traceToolOperation,
7: } from "./telemetry.ts";
8: 
9: export interface SpokenResult {
10:   sessionId: string;
11:   messageId: string | null;
12:   text: string;
13:   cost: number;
14: }
15: 
16: export interface PerformedResult extends SpokenResult {
17:   diff: string;
18: }
19: 
20: export interface SpiritGuide {
21:   speak(input: { role: "oracle" | "architect" | "witness"; conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<SpokenResult>;
22:   perform(input: { conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<PerformedResult>;
23:   inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown">;
24: }
25: 
26: const readOnlyPermissions = [
27:   { action: "edit", resource: "*", effect: "deny" as const },
28:   { action: "shell", resource: "*", effect: "deny" as const },
29:   { action: "external_directory", resource: "*", effect: "deny" as const },
30: ];
31: 
32: const makerPermissions = [
33:   { action: "shell", resource: "*", effect: "deny" as const },
34:   { action: "external_directory", resource: "*", effect: "deny" as const },
35:   { action: "edit", resource: "*", effect: "allow" as const },
36: ];
37: 
38: function assertFreeModel(model: { providerID: string; id: string } | undefined, cost: number): void {
39:   const selected = model ? `${model.providerID}/${model.id}` : "";
40:   if (selected !== FREE_DEEPSEEK_MODEL) {
41:     throw new Error("Native session left the required free DeepSeek model.");
42:   }
43:   if (cost > 0) throw new Error("Native session reported a non-zero cost.");
44: }
45: 
46: export class OpenCodeSpiritGuide implements SpiritGuide {
47:   constructor(private readonly options: NativeClientOptions) {}
48: 
49:   private client() {
50:     return createNativeClient(this.options);
51:   }
52: 
53:   private async openSession(role: "oracle" | "architect" | "maker" | "witness", conversationId: string, workspace: string, sessionId: string | null, permissions: Array<{ action: string; resource: string; effect: "allow" | "deny" | "ask" }>) {
54:     if (sessionId) return sessionId;
55:     return traceCreateAgent(role, conversationId, async (span) => {
56:       const created = await this.client().session.create({
57:         title: `Unfinished Business ${role}`,
58:         model: { providerID: "opencode", id: "deepseek-v4.1-flash-free" },
59:         location: { directory: workspace },
60:         permissions,
61:       });
62:       setOpenCodeResult(span, { sessionId: created.id });
63:       return created.id;
64:     });
65:   }
66: 
67:   async speak(input: { role: "oracle" | "architect" | "witness"; conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<SpokenResult> {
68:     return traceChatOperation(input.role, input.conversationId, async (span) => {
69:       const sessionId = await this.openSession(input.role, input.conversationId, input.workspace, input.sessionId, readOnlyPermissions);
70:       const generated = await this.client().session.generate({ sessionID: sessionId, prompt: input.prompt });
71:       let text = generated.text?.trim() ?? "";
72:       if (text.length < 80) {
73:         await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
74:         await Promise.race([
75:           this.client().session.wait({ sessionID: sessionId }),
76:           new Promise<never>((_, reject) => {
77:             setTimeout(() => reject(new Error("Native spirit timed out before it became idle.")), 90_000);
78:           }),
79:         ]);
80:         const listed = await this.client().message.list({ sessionID: sessionId, type: "assistant" });
81:         const messages = Array.isArray(listed) ? listed : listed.data;
82:         text = messages.flatMap((message) => message.type === "assistant" ? message.content : [])
83:           .flatMap((part) => part.type === "text" ? [part.text] : [])
84:           .join("\n")
85:           .trim();
86:       }
87:       const info = await this.client().session.get({ sessionID: sessionId });
88:       assertFreeModel(info.model, info.cost);
89:       if (!text) throw new Error("Native session returned no assistant text.");
90:       setOpenCodeResult(span, { sessionId, cost: info.cost });
91:       return { sessionId, messageId: null, text, cost: info.cost };
92:     });
93:   }
94: 
95:   async perform(input: { conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<PerformedResult> {
96:     return traceChatOperation("maker", input.conversationId, async (span) => {
97:       const sessionId = await this.openSession("maker", input.conversationId, input.workspace, input.sessionId, makerPermissions);
98:       const prompted = await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
99:       let timedOut = false;
100:       await Promise.race([
101:         this.client().session.wait({ sessionID: sessionId }),
102:         new Promise<void>((resolve) => {
103:           setTimeout(() => {
104:             timedOut = true;
105:             resolve();
106:           }, 180_000);
107:         }),
108:       ]);
109:       const info = await this.client().session.get({ sessionID: sessionId });
110:       assertFreeModel(info.model, info.cost);
111:       const diff = await traceToolOperation("maker", input.conversationId, "opencode.session.diff", async (toolSpan) => {
112:         const result = await this.client().session.diff({ sessionID: sessionId });
113:         setOpenCodeResult(toolSpan, { sessionId });
114:         toolSpan.setAttribute("opencode.diff.file_count", result.length);
115:         return result;
116:       });
117:       const summary = diff.length
118:         ? diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n")
119:         : timedOut
120:           ? "Native Maker run timed out before it became idle, without a file diff."
121:           : "Native session finished without a file diff.";
122:       const messageId = typeof prompted.id === "string" ? prompted.id : null;
123:       setOpenCodeResult(span, { sessionId, messageId, cost: info.cost });
124:       return { sessionId, messageId, text: summary, diff: summary, cost: info.cost };
125:     });
126:   }
127: 
128:   async inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown"> {
129:     return traceToolOperation(context.role, context.conversationId, "opencode.session.inspect", async (span) => {
130:       const info = await this.client().session.get({ sessionID: sessionId });
131:       setOpenCodeResult(span, { sessionId, cost: info.cost });
132:       if (info.outcome === "succeeded") return "succeeded";
133:       if (info.outcome === "failed" || info.outcome === "interrupted") return "failed";
134:       if (!info.time.idle) return "running";
135:       return "unknown";
136:     });
137:   }
138: }

