389: function statusLabel(section: WorkshopProject["sections"][number]): string {
390:   if (section.status === "DRAFT") return `Draft v${section.version}`;
391:   if (section.status === "NOT_STARTED") return "Not started";
392:   if (section.status === "APPROVED") return "Approved";
393:   return "Stale";
