58:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
59:   if (next.currentSectionId !== sectionId) throw new WorkflowConflict("Only the current section can be approved.");
60:   if (section.status !== "DRAFT" || section.version !== version || section.hash !== hash) {
