import {
  TOOL_CATALOG,
  TOOL_CATALOG_STALE_AFTER_DAYS,
  TOOL_CATALOG_VERIFIED_ON,
  TOOL_CATALOG_VERSION,
  type CatalogTool,
  type ToolCategory,
} from "./catalog.ts";

export type ToolDecisionStatus = "ADDED" | "DEFERRED" | "REJECTED";
export type DecisionState = "NONE" | ToolDecisionStatus;

export interface RecommendationDecision {
  toolId: string;
  status: ToolDecisionStatus;
}

export interface RecommendationConstraints {
  noSpend: boolean;
  localOnly: boolean;
  openSourceOnly: boolean;
  privacySensitive: boolean;
  deadlineHours: number | null;
  hardwareAvailable: "none" | "arduino" | "unknown";
  existingStack: string[];
}

export interface RecommendationInput {
  idea: string;
  sections?: Array<{ id: string; title: string; content: string; status?: string }>;
  needs?: ToolCategory[] | null;
  constraints?: Partial<RecommendationConstraints> | null;
  decisions?: RecommendationDecision[];
  planGate?: { productApproved: boolean; toolsSectionApproved: boolean };
  now?: string | Date;
  catalog?: CatalogTool[];
}

export interface RankedTool {
  tool: CatalogTool;
  rank: number;
  score: number;
  matchedNeeds: ToolCategory[];
  why: string[];
  whyNot: string[];
  prerequisites: string[];
  limitations: string[];
  fallback: string;
  stale: boolean;
  existing: boolean;
  baseline: boolean;
  decision: DecisionState;
  canAddToPlan: boolean;
}

export interface RecommendationResult {
  catalog: {
    version: string;
    verifiedOn: string;
    staleAfterDays: number;
    stale: boolean;
    oldestVerifiedOn: string;
    staleToolIds: string[];
  };
  idea: {
    textLength: number;
    needs: ToolCategory[];
    constraints: RecommendationConstraints;
  };
  baseline: RankedTool[];
  recommendations: RankedTool[];
  selected: RankedTool[];
  decisions: RecommendationDecision[];
  warnings: string[];
  canAddToPlan: boolean;
  toolsSectionApproved: boolean;
}

const NEED_ORDER: ToolCategory[] = [
  "web",
  "ai-inference",
  "fine-tuning",
  "tabular-data",
  "hardware",
  "voice",
  "browser-automation",
  "authentication",
  "search",
  "durable-workflows",
  "time-series-telemetry",
  "remote-database",
  "local-database",
  "vector-search",
  "public-deployment",
  "observability",
  "documentation",
  "ci",
  "code-history",
  "testing",
  "accessibility",
];

const NEED_PATTERNS: Array<[ToolCategory, RegExp]> = [
  ["web", /\b(web|website|web app|frontend|front-end|dashboard|react|html|css)\b/i],
  ["ai-inference", /\b(ai|llm|model|inference|assistant|chatbot|agent|machine learning|ml)\b/i],
  ["fine-tuning", /\b(fine[- ]?tun\w*|train\w*|lora|rlhf|reinforcement learning|dataset)\b/i],
  ["tabular-data", /\b(tabular|csv|spreadsheet|table|prediction|predict\w*|forecast\w*|classification|regression|feature engineering)\b/i],
  ["hardware", /\b(arduino|sensor|hardware|iot|microcontroller|device|robot|circuit)\b/i],
  ["voice", /\b(voice|speech|audio|tts|text[- ]to[- ]speech|transcri\w*|microphone|sound)\b/i],
  ["browser-automation", /\b(scrap(e|ing)|browser automation|automate (a )?browser|web automation|playwright|stagehand|headless browser|logged[- ]in)\b/i],
  ["authentication", /\b(auth|authentication|authorization|login|log[- ]in|sign[- ]in|oauth|user accounts?|identity|permissions?)\b/i],
  ["search", /\b(search|serp|google results|web results|find information|lookup)\b/i],
  ["durable-workflows", /\b(workflow\w*|durable|retry|retries|background job|long[- ]running|queue|orchestration|schedule(d)? task)\b/i],
  ["time-series-telemetry", /\b(time[- ]series|telemetry|metrics|monitor(ing)?|observability|trace(s|ing)?|logs?|sensor data)\b/i],
  ["remote-database", /\b(remote database|cloud database|managed database|postgres|mongodb|mysql|atlas|multi[- ]user|shared data)\b/i],
  ["local-database", /\b(sqlite|local database|embedded database|offline data|single[- ]file database)\b/i],
  ["vector-search", /\b(vector|embedding|semantic search|rag|similarity search)\b/i],
  ["public-deployment", /\b(deploy\w*|hosted|public url|live site|production|share a link|domain)\b/i],
  ["observability", /\b(error tracking|sentry|observability|monitoring|instrumentation)\b/i],
  ["documentation", /\b(diagram|flowchart|architecture diagram|documentation|sequence diagram|mermaid)\b/i],
  ["ci", /\b(ci|continuous integration|github actions|pipeline|automated tests?)\b/i],
  ["code-history", /\b(session history|checkpoint|why (the )?code exists|agent history|entire)\b/i],
  ["testing", /\b(test|tests|testing|e2e|end[- ]to[- ]end|playwright|axe)\b/i],
  ["accessibility", /\b(accessib\w*|wcag|a11y|screen reader|keyboard navigation|contrast)\b/i],
];

const TOOL_ALIASES: Array<[string, RegExp]> = [
  ["opencode", /\bopencode\b/i],
  ["entire", /\bentire\b/i],
  ["sentry-agent-tracing", /\bsentry\b/i],
