  ["ollama", /\bollama\b/i],
  ["sqlite", /\bsqlite\b/i],
  ["playwright", /\bplaywright\b/i],
  ["axe-core", /\baxe(?:-core)?\b/i],
  ["opentelemetry", /\bopentelemetry\b|\botel\b/i],
  ["mermaid", /\bmermaid\b/i],
  ["github-actions", /\bgithub actions\b/i],
  ["tabpfn", /\btabpfn\b/i],
  ["tinker", /\btinker\b/i],
  ["arduino", /\barduino\b/i],
  ["digitalocean", /\bdigitalocean\b|\bdigital ocean\b/i],
  ["auth0-ai-agents", /\bauth0\b/i],
  ["backboard", /\bbackboard\b/i],
  ["elevenlabs", /\belevenlabs\b/i],
  ["browserbase-stagehand", /\bbrowserbase\b|\bstagehand\b/i],
  ["github-copilot", /\bcopilot\b/i],
  ["mastra", /\bmastra\b/i],
  ["mongodb-atlas", /\bmongodb\b|\batlas\b/i],
  ["ultramarine", /\bultramarine\b/i],
  ["serpapi", /\bserpapi\b/i],
  ["tech-domain", /\.tech\b/i],
  ["temporal", /\btemporal\b/i],
  ["tiger-data", /\btiger data\b|\btimescale\w*\b/i],
];

const PROMOTIONAL_KINDS = new Set(["trial"]);

function uniq<T>(values: T[]): T[] {
  return [...new Set(values)];
}

export function extractNeeds(text: string): ToolCategory[] {
  const found = NEED_PATTERNS
    .filter(([, pattern]) => pattern.test(text))
    .map(([need]) => need);
  return NEED_ORDER.filter((need) => found.includes(need));
}

export function extractExistingStack(text: string): string[] {
  return TOOL_ALIASES
    .filter(([, pattern]) => pattern.test(text))
    .map(([id]) => id);
}

export function extractConstraints(text: string): Partial<RecommendationConstraints> {
  const hours = (() => {
    const hourMatch = text.match(/(\d+)\s*(?:hours?|hrs?)\b/i);
    if (hourMatch) return Number(hourMatch[1]);
    const dayMatch = text.match(/(\d+)\s*days?\b/i);
    if (dayMatch) return Number(dayMatch[1]) * 24;
    return undefined;
  })();
  const noSpend = /\b(no spend\w*|no budget|zero[- ]cost|\$0|free only|without spending|no new spending)\b/i.test(text)
    ? true
    : /\b(budget|credit|credits)\b/i.test(text)
      ? undefined
      : undefined;
  return {
    noSpend,
    localOnly: /\b(local[- ]only|offline|on[- ]device|no cloud|self[- ]hosted only|private machine)\b/i.test(text) ? true : undefined,
    openSourceOnly: /\b(open[- ]source only|open source only|no proprietary|open[- ]only)\b/i.test(text) ? true : undefined,
    privacySensitive: /\b(private|privacy[- ]sensitive|sensitive data|personal data|patient data|confidential)\b/i.test(text) ? true : undefined,
    deadlineHours: hours,
    hardwareAvailable: /\b(no hardware|without hardware|no arduino|hardware unavailable)\b/i.test(text)
      ? "none"
      : /\barduino\b/i.test(text)
        ? "arduino"
        : undefined,
  };
}

export function resolveConstraints(
  text: string,
  explicit?: Partial<RecommendationConstraints> | null,
): RecommendationConstraints {
  const extracted = extractConstraints(text);
  return {
    // The product's cash cap is $0, so no-spend is the safe default.
    noSpend: explicit?.noSpend ?? extracted.noSpend ?? true,
    localOnly: explicit?.localOnly ?? extracted.localOnly ?? false,
    openSourceOnly: explicit?.openSourceOnly ?? extracted.openSourceOnly ?? false,
    privacySensitive: explicit?.privacySensitive ?? extracted.privacySensitive ?? false,
    deadlineHours: explicit?.deadlineHours ?? extracted.deadlineHours ?? null,
    hardwareAvailable: explicit?.hardwareAvailable ?? extracted.hardwareAvailable ?? "unknown",
    existingStack: uniq(explicit?.existingStack ?? extractExistingStack(text)),
  };
}

function toolText(tool: CatalogTool): string {
  return [tool.name, ...tool.capabilities, ...tool.categories].join(" ").toLowerCase();
}

function matchesNeeds(tool: CatalogTool, needs: ToolCategory[]): ToolCategory[] {
  return tool.categories.filter((category) => needs.includes(category));
}

function daysBetween(from: string, to: string): number {
  const start = Date.parse(`${from}T00:00:00Z`);
  const end = Date.parse(`${to}T00:00:00Z`);
  return Math.floor((end - start) / 86_400_000);
}

export function isToolStale(tool: CatalogTool, now: string | Date, staleAfterDays = TOOL_CATALOG_STALE_AFTER_DAYS): boolean {
  const today = typeof now === "string" ? now.slice(0, 10) : now.toISOString().slice(0, 10);
  return daysBetween(tool.lastVerified, today) > staleAfterDays;
}

function reasonForNeed(need: ToolCategory): string {
  return `Matches the ${need.replace(/-/g, " ")} need in this idea.`;
}

function opennessReason(tool: CatalogTool): string | null {
  if (tool.openness === "open-source") return `Open source under ${tool.license}; you can inspect and self-host it.`;
  if (tool.openness === "open-weight") return "Open weights under a separate model licence; review that licence before redistribution or production use.";
  if (tool.openness === "mixed") return "Mixed licensing: only some components are open; the proprietary components carry separate terms.";
  return null;
}

function costReason(tool: CatalogTool): string {
  if (tool.cost.promotional || PROMOTIONAL_KINDS.has(tool.cost.kind)) {
    return "Promotional or trial access can reduce cost during the event, but it is not permanent free usage.";
  }
  if (tool.cost.kind === "paid-only") return "Paid-only access requires an explicit budget before use.";
  if (tool.cost.permanentFree) return "Has a permanent free/open path, not only trial credit.";
  if (tool.cost.freeTier) return "Has a limited free tier; check the current quota before relying on it.";
  return "Usage is metered or paid; budget approval is required before use.";
}

function baseWhy(tool: CatalogTool, matched: ToolCategory[], constraints: RecommendationConstraints, existing: boolean): string[] {
  const why = matched.map(reasonForNeed);
  const openness = opennessReason(tool);
  if (openness) why.push(openness);
  if (tool.selfHost === "yes") why.push("Can run locally or on infrastructure you control.");
  else if (tool.selfHost === "partial") why.push("Some components can run locally; the managed part still depends on a provider.");
  why.push(costReason(tool));
  if (tool.effort === "low") why.push("Low setup effort is a good fit for a short build window.");
  if (existing) why.push("Already in your existing stack, so no switch is needed.");
  if (constraints.noSpend && tool.cost.permanentFree) why.push("Fits the no-spending constraint through its open or permanent-free path.");
  if (constraints.localOnly && tool.selfHost !== "no") why.push("Fits the local-only constraint for at least the core workflow.");
  if (constraints.openSourceOnly && tool.openness === "open-source") why.push("Fits the open-source-only constraint.");
  return uniq(why);
}

function baseWhyNot(tool: CatalogTool, matched: ToolCategory[], constraints: RecommendationConstraints): string[] {
  const whyNot: string[] = [];
  if (matched.length === 0) whyNot.push("No clear need match was found in the idea text.");
  if (tool.status === "excluded") whyNot.push("Excluded from this product's harness choices.");
  if (tool.harnessAlternative) whyNot.push("OpenCode is the only harness; a harness switch is not recommended.");
  if (tool.cost.promotional || PROMOTIONAL_KINDS.has(tool.cost.kind)) {
    whyNot.push("Promotional credit or trial access is temporary and must not be treated as permanent free usage.");
  }
  if (tool.cost.kind === "paid-only") whyNot.push("Paid-only access conflicts with a no-spend constraint.");
  if (tool.cost.kind === "hardware") whyNot.push("Requires physical hardware and components in addition to software.");
  if (tool.openness === "proprietary" && constraints.openSourceOnly) whyNot.push("Proprietary; conflicts with open-source-only.");
  if (tool.openness === "mixed" && constraints.openSourceOnly) whyNot.push("Mixed licensing means part of the stack is not open source.");
  if (constraints.localOnly && tool.selfHost === "no") whyNot.push("Hosted-only service conflicts with local-only.");
  if (constraints.privacySensitive && tool.setupMode === "hosted" && tool.selfHost === "no") {
    whyNot.push("Sends data to a hosted service; review the privacy constraint before adding it.");
  }
  if (constraints.deadlineHours !== null && constraints.deadlineHours <= 24 && tool.effort === "high") {
    whyNot.push("High integration effort may not fit a deadline of 24 hours or less.");
  }
  if (constraints.hardwareAvailable === "none" && tool.categories.includes("hardware")) {
    whyNot.push("Hardware is unavailable for this project.");
  }
  if (tool.role === "application" && (tool.id === "mastra" || tool.id === "backboard")) {
    whyNot.push("For an application the user builds, not for this workshop's internal orchestration.");
  }
  whyNot.push("No challenge category is claimed from a tool name alone; implemented usage and evidence are required.");
  return uniq(whyNot);
}

function scoreTool(
  tool: CatalogTool,
  matched: ToolCategory[],
  constraints: RecommendationConstraints,
  decision: DecisionState,
): number {
  const statusScore = tool.status === "core" ? 24 : tool.status === "conditional" ? 18 : tool.status === "promo-only" ? 8 : -100;
  let score = statusScore + Math.min(matched.length, 3) * 12;

  if (constraints.noSpend) {
    if (tool.cost.kind === "paid-only") score -= 40;
    else if (tool.cost.promotional || PROMOTIONAL_KINDS.has(tool.cost.kind)) score -= 14;
    else if (tool.cost.permanentFree) score += 10;
    else score -= 4;
  }
  if (constraints.localOnly) {
    if (tool.selfHost === "yes") score += 10;
    else if (tool.selfHost === "partial") score -= 3;
    else score -= 18;
  }
  if (constraints.openSourceOnly) {
    if (tool.openness === "open-source") score += 10;
    else if (tool.openness === "open-weight") score += 3;
    else if (tool.openness === "mixed") score -= 8;
    else score -= 24;
  }
  if (constraints.privacySensitive) {
    if (tool.selfHost === "yes") score += 6;
    if (tool.setupMode === "hosted" && tool.selfHost === "no") score -= 12;
  }
  if (constraints.deadlineHours !== null && constraints.deadlineHours <= 24) {
    if (tool.effort === "low") score += 8;
    else if (tool.effort === "medium") score -= 2;
    else score -= 10;
  }
  if (constraints.hardwareAvailable === "none" && tool.categories.includes("hardware")) score -= 40;
  if (constraints.existingStack.includes(tool.id)) score += 6;
  if (decision === "DEFERRED") score -= 3;
  if (decision === "REJECTED") score -= 100;

  return score;
}

function isEligible(tool: CatalogTool, constraints: RecommendationConstraints): boolean {
  if (tool.status === "excluded") return false;
  if (tool.harnessAlternative) return false;
  if (constraints.noSpend && tool.cost.kind === "paid-only") return false;
  if (constraints.noSpend && tool.cost.kind === "hardware") return false;
  if (constraints.localOnly && tool.setupMode === "hosted" && tool.selfHost !== "yes") return false;
  if (constraints.privacySensitive && tool.setupMode === "hosted" && tool.selfHost === "no") return false;
  if (constraints.openSourceOnly && tool.openness === "proprietary") return false;
  if (constraints.hardwareAvailable === "none" && tool.categories.includes("hardware")) return false;
  return true;
}

function rankTool(
  tool: CatalogTool,
  matched: ToolCategory[],
  constraints: RecommendationConstraints,
  decision: DecisionState,
  now: string,
  canAddToPlan: boolean,
  baseline: boolean,
): RankedTool {
  return {
    tool,
    rank: 0,
    score: scoreTool(tool, matched, constraints, decision),
    matchedNeeds: matched,
    why: baseWhy(tool, matched, constraints, constraints.existingStack.includes(tool.id)),
    whyNot: baseWhyNot(tool, matched, constraints),
    prerequisites: [...tool.prerequisites],
    limitations: [
      ...tool.cost.limits,
      "Adding this recommendation does not install it, create an account, claim credit, deploy, or authorize spending.",
    ],
    fallback: tool.fallback,
    stale: isToolStale(tool, now),
    existing: constraints.existingStack.includes(tool.id),
    baseline,
    decision,
    canAddToPlan: canAddToPlan && !baseline && decision !== "ADDED" && decision !== "REJECTED" && tool.status !== "excluded",
  };
}

export function recommend(input: RecommendationInput): RecommendationResult {
  const catalog = input.catalog ?? TOOL_CATALOG;
  const now = typeof input.now === "string" ? input.now.slice(0, 10) : (input.now ?? new Date()).toISOString().slice(0, 10);
  const idea = input.idea ?? "";
  const sectionText = (input.sections ?? []).map((section) => `${section.title}\n${section.content}`).join("\n");
  const sourceText = [idea, sectionText].filter(Boolean).join("\n");
  const needs = input.needs?.length ? uniq(input.needs) : extractNeeds(sourceText);
  const constraints = resolveConstraints(sourceText, input.constraints);
  const decisions = input.decisions ?? [];
  const decisionFor = (toolId: string): DecisionState => decisions.find((decision) => decision.toolId === toolId)?.status ?? "NONE";
  const planGate = input.planGate ?? { productApproved: false, toolsSectionApproved: false };
  const canAddToPlan = planGate.productApproved && planGate.toolsSectionApproved;

  const staleToolIds = catalog.filter((tool) => isToolStale(tool, now)).map((tool) => tool.id);
  const oldestVerifiedOn = catalog.reduce(
    (oldest, tool) => tool.lastVerified < oldest ? tool.lastVerified : oldest,
    catalog[0]?.lastVerified ?? TOOL_CATALOG_VERIFIED_ON,
  );

  const baseline = catalog
    .filter((tool) => tool.role === "product-harness" || tool.role === "build-history")
    .filter((tool) => tool.id !== "github-copilot")
    .map((tool) => rankTool(tool, matchesNeeds(tool, needs), constraints, decisionFor(tool.id), now, false, true));

  const candidates: RankedTool[] = [];
  for (const tool of catalog) {
    if (tool.role === "product-harness" || tool.role === "build-history") continue;
    if (!isEligible(tool, constraints)) continue;
    const matched = matchesNeeds(tool, needs);
    if (matched.length === 0) continue;
    const decision = decisionFor(tool.id);
    if (decision === "REJECTED" || decision === "ADDED") continue;
    candidates.push(rankTool(tool, matched, constraints, decision, now, canAddToPlan, false));
  }

  candidates.sort((left, right) => {
    if (right.score !== left.score) return right.score - left.score;
    if (left.tool.status !== right.tool.status) {
      const order = { core: 0, conditional: 1, "promo-only": 2, excluded: 3 } as const;
      return order[left.tool.status] - order[right.tool.status];
    }
    return left.tool.id.localeCompare(right.tool.id);
  });

  const ranked = candidates.slice(0, 5).map((candidate, index) => ({ ...candidate, rank: index + 1 }));

  const selected = decisions
    .filter((decision) => decision.status === "ADDED")
    .map((decision) => catalog.find((tool) => tool.id === decision.toolId))
    .filter((tool): tool is CatalogTool => Boolean(tool))
    .map((tool) => rankTool(tool, matchesNeeds(tool, needs), constraints, "ADDED", now, false, false));

  const warnings: string[] = [];
  if (staleToolIds.length) {
    warnings.push(`Catalog data is stale for ${staleToolIds.length} tool(s). Re-check official sources before relying on cost, licence, or quota facts.`);
  }
  if (constraints.noSpend) {
    warnings.push("No-spending is on: trial and promotional credit is not treated as permanent free usage.");
  }
  if (constraints.localOnly) {
    warnings.push("Local-only is on: hosted-only tools are excluded from recommendations.");
  }
  if (constraints.openSourceOnly) {
    warnings.push("Open-source-only is on: proprietary tools are excluded and mixed-licence tools are down-ranked.");
  }
  if (needs.length === 0) {
    warnings.push("No structured need was detected. Add a clearer idea or choose needs explicitly.");
  }

  return {
    catalog: {
      version: TOOL_CATALOG_VERSION,
      verifiedOn: TOOL_CATALOG_VERIFIED_ON,
      staleAfterDays: TOOL_CATALOG_STALE_AFTER_DAYS,
      stale: staleToolIds.length > 0,
      oldestVerifiedOn,
      staleToolIds,
    },
    idea: {
      textLength: sourceText.length,
      needs,
      constraints,
    },
    baseline,
    recommendations: ranked,
    selected,
    decisions,
    warnings,
    canAddToPlan,
    toolsSectionApproved: planGate.toolsSectionApproved,
  };
}

/**
 * Explain why a tool was not returned. Used by tests and documentation to make
 * exclusions inspectable without leaking an unsupported claim into the UI.
 */
export function explainExclusion(input: RecommendationInput, toolId: string): string[] {
  const catalog = input.catalog ?? TOOL_CATALOG;
  const tool = catalog.find((entry) => entry.id === toolId);
  if (!tool) return ["That tool is not in the catalog."];
  const constraints = resolveConstraints(input.idea, input.constraints);
  const needs = input.needs?.length ? input.needs : extractNeeds(input.idea);
  const reasons: string[] = [];
  if (tool.status === "excluded") reasons.push("It is excluded by product policy.");
  if (tool.harnessAlternative) reasons.push("OpenCode is the only harness.");
  if (constraints.noSpend && tool.cost.kind === "paid-only") reasons.push("It is paid-only under a no-spend constraint.");
  if (constraints.localOnly && tool.setupMode === "hosted" && tool.selfHost !== "yes") reasons.push("It is hosted-only under a local-only constraint.");
  if (constraints.openSourceOnly && tool.openness === "proprietary") reasons.push("It is proprietary under an open-source-only constraint.");
  if (constraints.hardwareAvailable === "none" && tool.categories.includes("hardware")) reasons.push("Hardware is unavailable.");
  if (matchesNeeds(tool, needs).length === 0) reasons.push("The idea does not express a matching need.");
  return reasons.length ? reasons : ["It did not rank in the small recommendation set."];
}

