import { catalogTool, TOOL_CATALOG_VERIFIED_ON, TOOL_CATALOG_VERSION, type ToolCategory } from "./catalog.ts";
import {
  extractNeeds,
  NEED_ORDER,
  recommend,
  type RecommendationConstraints,
  type RecommendationResult,
  type ToolDecisionStatus,
} from "./engine.ts";
import type { Project } from "../workflow/model.ts";
import { refreshNextAction } from "../workflow/model.ts";
import { AtomicProjectStore } from "../store/atomic-project-store.ts";
import { WorkflowConflict, rememberTranscript } from "../workflow/transitions.ts";
import { WorkflowService } from "../workflow/service.ts";

export interface RecommendationContextInput {
  needs: ToolCategory[] | null;
  constraints: {
    noSpend: boolean | null;
    localOnly: boolean | null;
    openSourceOnly: boolean | null;
    privacySensitive: boolean | null;
    deadlineHours: number | null;
    hardwareAvailable: "none" | "arduino" | "unknown" | null;
    existingStack: string[];
  };
}

const NEED_SET = new Set<string>(NEED_ORDER);

function sanitizeNeeds(needs: string[] | null): ToolCategory[] | null {
  if (!needs) return null;
  return NEED_ORDER.filter((need) => NEED_SET.has(need) && needs.includes(need));
}

function contextConstraints(project: Project): Partial<RecommendationConstraints> {
  const constraints = project.recommendationContext.constraints;
  return {
    noSpend: constraints.noSpend ?? undefined,
    localOnly: constraints.localOnly ?? undefined,
    openSourceOnly: constraints.openSourceOnly ?? undefined,
    privacySensitive: constraints.privacySensitive ?? undefined,
    deadlineHours: constraints.deadlineHours ?? undefined,
    hardwareAvailable: constraints.hardwareAvailable ?? undefined,
    existingStack: constraints.existingStack,
  };
}

export class RecommendationService {
  constructor(
    private readonly workflow: WorkflowService,
    private readonly store: AtomicProjectStore,
  ) {}

  async forProject(): Promise<RecommendationResult> {
    return this.build(await this.workflow.get());
  }

  build(project: Project): RecommendationResult {
    const toolsSectionApproved = project.sections.find((section) => section.id === "tools")?.status === "APPROVED";
    const idea = [
      project.product.proposal ?? "",
      ...project.product.openQuestions,
      project.sections.find((section) => section.id === "tools")?.content ?? "",
    ].join("\n");
    return recommend({
      idea,
      sections: project.sections.map((section) => ({
        id: section.id,
        title: section.title,
        content: section.content,
        status: section.status,
      })),
      needs: sanitizeNeeds(project.recommendationContext.needs),
      constraints: contextConstraints(project),
      decisions: project.toolDecisions.map((decision) => ({ toolId: decision.toolId, status: decision.status })),
      planGate: {
        productApproved: project.product.status === "APPROVED",
        toolsSectionApproved,
      },
    });
  }

  async decide(
    actionId: string,
    expectedRevision: number,
    toolId: string,
    status: ToolDecisionStatus,
    note: string | null = null,
  ) {
    const payload = { toolId, status, note };
    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
      if (project.product.status !== "APPROVED") {
        throw new WorkflowConflict("Approve the product before deciding on tools.");
      }
      const tool = catalogTool(toolId);
      if (!tool) throw new WorkflowConflict(`Unknown tool: ${toolId}`);
      if (tool.status === "excluded" || tool.harnessAlternative) {
        throw new WorkflowConflict("That tool is excluded from this product's harness choices.");
      }
