          throw new WorkflowConflict("Approve the Tools, access, and cost section before adding a tool to the plan.");
        }
        if (constraints.noSpend !== false && tool.cost.kind === "paid-only") {
          throw new WorkflowConflict("That tool is paid-only and the project has a no-spending constraint.");
        }
      }

      const next = structuredClone(project);
      const decidedAt = new Date().toISOString();
      const decision = {
        toolId,
        status,
        decidedAt,
        catalogVersion: TOOL_CATALOG_VERSION,
        catalogVerifiedOn: TOOL_CATALOG_VERIFIED_ON,
        note,
      };
      const index = next.toolDecisions.findIndex((item) => item.toolId === toolId);
      if (index >= 0) next.toolDecisions[index] = decision;
      else next.toolDecisions.push(decision);
      rememberTranscript(next, "user", `${status === "ADDED" ? "Added" : status === "DEFERRED" ? "Deferred" : "Rejected"} ${tool.name} for the plan. This did not install or authorize spending.`);
      return refreshNextAction(next);
    });
  }

  async updateContext(actionId: string, expectedRevision: number, input: RecommendationContextInput) {
    const payload = {
      needs: input.needs,
      constraints: input.constraints,
    };
    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
      if (project.product.status !== "APPROVED") {
        throw new WorkflowConflict("Approve the product before changing recommendation filters.");
      }
      const next = structuredClone(project);
      next.recommendationContext = {
        needs: sanitizeNeeds(input.needs),
        constraints: {
          noSpend: input.constraints.noSpend,
          localOnly: input.constraints.localOnly,
          openSourceOnly: input.constraints.openSourceOnly,
          privacySensitive: input.constraints.privacySensitive,
          deadlineHours: input.constraints.deadlineHours,
          hardwareAvailable: input.constraints.hardwareAvailable,
          existingStack: [...new Set(input.constraints.existingStack)],
        },
        updatedAt: new Date().toISOString(),
      };
      return refreshNextAction(next);
    });
  }
}

