    openSourceOnly: boolean | null;
    privacySensitive: boolean | null;
    deadlineHours: number | null;
    hardwareAvailable: "none" | "arduino" | "unknown" | null;
    existingStack: string[];
  };
}

const NEED_SET = new Set<string>(NEED_ORDER);

function sanitizeNeeds(needs: string[] | null): ToolCategory[] | null {
  if (!needs) return null;
  return NEED_ORDER.filter((need) => NEED_SET.has(need) && needs.includes(need));
}

function contextConstraints(project: Project): Partial<RecommendationConstraints> {
  const constraints = project.recommendationContext.constraints;
  return {
    noSpend: constraints.noSpend ?? undefined,
    localOnly: constraints.localOnly ?? undefined,
    openSourceOnly: constraints.openSourceOnly ?? undefined,
    privacySensitive: constraints.privacySensitive ?? undefined,
    deadlineHours: constraints.deadlineHours ?? undefined,
    hardwareAvailable: constraints.hardwareAvailable ?? undefined,
    existingStack: constraints.existingStack,
  };
}

