input.newString:
async exportApproved() {
  const project = await this.workflow.get();
  const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
  const plan = unresolved.length
    ? null
    : project.sections
      .toSorted((left, right) => left.order - right.order)
      .map((section) => `## ${section.title}\n\n${section.content}`)
      .join("\n\n");
  const toolDecisions = project.toolDecisions.map((decision) => {
    const tool = catalogTool(decision.toolId);
    return {
      toolId: decision.toolId,
      name: tool?.name ?? decision.toolId,
      status: decision.status,
      catalogVersion: decision.catalogVersion,
      catalogVerifiedOn: decision.catalogVerifiedOn,
      openness: tool?.openness ?? null,
      license: tool?.license ?? null,
      costSummary: tool?.cost.summary ?? null,
      sources: tool?.sources ?? [],
      note: decision.note,
    };
  });
  return {
    plan,
    unresolved: unresolved.map((section) => section.id),
    drafts: project.witnessDrafts.map((draft) => ({ title: draft.title, content: draft.content })),
    selectedTools: toolDecisions.filter((decision) => decision.status === "ADDED"),
    toolDecisions,
    limitation: "Witness drafts and selected tools are in-app planning notes. They are not a submitted article, video, or entry. Selecting a tool does not install it, create an account, claim credit, deploy, or authorize spending.",
  };
}

