export function loadExport() {
  return request<{
    plan: string | null;
    unresolved: string[];
    drafts: Array<{ title: string; content: string }>;
    selectedTools: Array<{ toolId: string; name: string; status: string }>;
    toolDecisions: Array<{ toolId: string; name: string; status: string }>;
    limitation: string;
  }>("/api/export");
}

export function loadRecommendations() {
  return request<RecommendationResult>("/api/recommendations");
}

export function updateRecommendationContext(
  project: WorkshopProject,
  input: {
    needs: string[] | null;
    constraints: {
      noSpend: boolean | null;
      localOnly: boolean | null;
      openSourceOnly: boolean | null;
      privacySensitive: boolean | null;
      deadlineHours: number | null;
      hardwareAvailable: "none" | "arduino" | "unknown" | null;
      existingStack: string[];
    };
  },
) {
  return request<RecommendationAction>("/api/recommendations/context", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, ...input },
  });
}

export function decideTool(
  project: WorkshopProject,
  toolId: string,
  status: ToolDecisionStatus,
  note: string | null = null,
) {
  return request<RecommendationAction>(`/api/recommendations/${encodeURIComponent(toolId)}/decisions`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, status, note },
  });
}

