function ToolRecommendations(props: {
  project: WorkshopProject;
  result: RecommendationResult | null;
  error: string | null;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject; recommendations?: RecommendationResult }>) => Promise<void>;
}) {
  const result = props.result;
  const [noSpend, setNoSpend] = useState(result?.idea.constraints.noSpend ?? true);
  const [localOnly, setLocalOnly] = useState(result?.idea.constraints.localOnly ?? false);
  const [openSourceOnly, setOpenSourceOnly] = useState(result?.idea.constraints.openSourceOnly ?? false);
  const [privacySensitive, setPrivacySensitive] = useState(result?.idea.constraints.privacySensitive ?? false);
  const [deadline, setDeadline] = useState(result?.idea.constraints.deadlineHours?.toString() ?? "");
  const [hardware, setHardware] = useState<"none" | "arduino" | "unknown">(result?.idea.constraints.hardwareAvailable ?? "unknown");
  const [focusNeed, setFocusNeed] = useState("all");
  const [initialized, setInitialized] = useState(Boolean(result));

  useEffect(() => {
    if (!result || initialized) return;
    setNoSpend(result.idea.constraints.noSpend);
    setLocalOnly(result.idea.constraints.localOnly);
    setOpenSourceOnly(result.idea.constraints.openSourceOnly);
    setPrivacySensitive(result.idea.constraints.privacySensitive);
    setDeadline(result.idea.constraints.deadlineHours?.toString() ?? "");
    setHardware(result.idea.constraints.hardwareAvailable);
    setInitialized(true);
  }, [result, initialized]);

  if (props.error) return <p className="banner bad" role="alert">{props.error}</p>;
  if (!result) return <p className="banner" role="status">Reading the approved idea for tool needs…</p>;

  const apply = () => void props.act(() => updateRecommendationContext(props.project, {
    needs: focusNeed === "all" ? null : [focusNeed],
    constraints: {
      noSpend,
      localOnly,
      openSourceOnly,
      privacySensitive,
      deadlineHours: deadline.trim() === "" ? null : Number(deadline),
      hardwareAvailable: hardware,
      existingStack: result.idea.constraints.existingStack,
    },
  }));

  const decide = (toolId: string, status: ToolDecisionStatus) => void props.act(() => decideTool(props.project, toolId, status));

  return (
    <section className="tools" aria-labelledby="tools-heading">
      <p className="eyebrow">Tools &amp; budget</p>
      <h2 id="tools-heading">Idea-aware recommendations</h2>
      <p className="meta">
        Catalog {result.catalog.version} · verified {result.catalog.verifiedOn} · stale after {result.catalog.staleAfterDays} days
      </p>
      {result.catalog.stale ? (
        <p className="banner bad" role="alert">
          <ShieldAlert aria-hidden="true" size={16} /> Some catalog facts are past the verification window. Re-check the linked official sources before relying on cost, licence, or quota claims.
        </p>
      ) : null}
      {result.warnings.map((warning) => <p className="banner" role="status" key={warning}>{warning}</p>)}

      <div className="filters">
        <fieldset>
          <legend>Detected needs</legend>
          <div className="chips">
            {result.idea.needs.length ? result.idea.needs.map((need) => (
              <span className="chip active" key={need}>{need}</span>
            )) : <span className="note">No need detected yet.</span>}
          </div>
          <label>
            Focus a need
            <select value={focusNeed} onChange={(event) => setFocusNeed(event.target.value)}>
              <option value="all">All detected needs</option>
              {[...new Set([...result.idea.needs, "web", "ai-inference", "local-database", "remote-database", "authentication", "voice", "browser-automation", "search", "durable-workflows", "time-series-telemetry", "vector-search", "public-deployment", "hardware", "testing", "accessibility"])].map((need) => (
                <option value={need} key={need}>{need}</option>
              ))}
            </select>
          </label>
        </fieldset>
        <fieldset>
          <legend>Constraints</legend>
          <label className="check"><input type="checkbox" checked={noSpend} onChange={(event) => setNoSpend(event.target.checked)} /> No spending</label>
          <label className="check"><input type="checkbox" checked={localOnly} onChange={(event) => setLocalOnly(event.target.checked)} /> Local only</label>
          <label className="check"><input type="checkbox" checked={openSourceOnly} onChange={(event) => setOpenSourceOnly(event.target.checked)} /> Open source only</label>
          <label className="check"><input type="checkbox" checked={privacySensitive} onChange={(event) => setPrivacySensitive(event.target.checked)} /> Privacy-sensitive data</label>
          <label>
            Deadline hours
            <input type="number" min="0" max="2000" value={deadline} onChange={(event) => setDeadline(event.target.value)} placeholder="e.g. 24" />
          </label>
          <label>
            Hardware
            <select value={hardware} onChange={(event) => setHardware(event.target.value as "none" | "arduino" | "unknown")}>
              <option value="unknown">Unknown</option>
              <option value="none">None available</option>
              <option value="arduino">Arduino available</option>
            </select>
          </label>
        </fieldset>
        <button className="action secondary" type="button" onClick={apply} disabled={props.busy}>Apply filters</button>
      </div>

      <p className="note">
        Recommendations are deterministic and based on the approved idea plus these constraints. Adding a tool records a planning decision only. It does not install software, create an account, claim a credit, deploy, or authorize spending.
      </p>
      {!result.canAddToPlan ? (
        <p className="banner" role="status">
          <Clock aria-hidden="true" size={16} /> Approve the <strong>Tools, access, and cost</strong> section before adding a tool. Recommendations are still available to inform that draft.
        </p>
      ) : null}

      <div className="tool-grid">
        {result.recommendations.map((item) => (
          <ToolCard key={item.tool.id} item={item} busy={props.busy} onDecide={decide} />
        ))}
      </div>
      {result.recommendations.length === 0 ? (
        <p className="banner">No tool matched this combination. Clear a constraint, choose a need, or add more detail to the idea. OpenCode and Entire remain the workshop baseline.</p>
      ) : null}

      <details className="baseline">
        <summary>Workshop baseline — {result.baseline.map((item) => item.tool.name).join(", ")}</summary>
        <ul className="source-list">
          {result.baseline.map((item) => (
            <li key={item.tool.id}>
              <strong>{item.tool.name}</strong> — {item.tool.license}. {item.tool.notes} <span className="meta">Verified {item.tool.lastVerified}.</span>
            </li>
          ))}
        </ul>
        <p className="note">OpenCode is the only harness. A baseline entry is not ranked against alternatives and does not trigger an install or account action.</p>
      </details>

      {result.selected.length ? (
        <section className="selected-tools">
          <h3>Added to the plan</h3>
          <ul className="source-list">
            {result.selected.map((item) => (
              <li key={item.tool.id}>
                <strong>{item.tool.name}</strong> — {item.tool.openness}; {item.tool.cost.summary} <span className="meta">Verified {item.tool.lastVerified}.</span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
    </section>
  );
}

function ToolCard(props: {
  item: ToolRecommendation;
  busy: boolean;
  onDecide: (toolId: string, status: ToolDecisionStatus) => void;
}) {
  const { item } = props;
  const tool = item.tool;
  return (
    <article className={item.decision === "NONE" ? "tool-card" : "tool-card decided"}>
