const GENERIC_NEEDS = new Set<ToolCategory>(["web", "ai-inference"]);

const NEED_WEIGHT: Record<ToolCategory, number> = {
  web: 3,
  "ai-inference": 3,
  "fine-tuning": 10,
  "tabular-data": 12,
  hardware: 12,
  voice: 12,
  "browser-automation": 10,
  authentication: 10,
  search: 7,
  "durable-workflows": 10,
  "time-series-telemetry": 9,
  "remote-database": 9,
  "local-database": 8,
  "vector-search": 9,
  "public-deployment": 5,
  observability: 8,
  documentation: 4,
  ci: 4,
  "code-history": 4,
  testing: 5,
  accessibility: 7,
};

function matchesNeeds(tool: CatalogTool, needs: ToolCategory[]): ToolCategory[] {
  return tool.categories.filter((category) => needs.includes(category));
}

function needFitScore(matched: ToolCategory[], needs: ToolCategory[]): number {
  const primary = needs.find((need) => !GENERIC_NEEDS.has(need)) ?? needs[0] ?? null;
  const weight = matched.reduce((total, need) => total + NEED_WEIGHT[need], 0);
  const primaryBonus = primary && matched.includes(primary) ? 6 : 0;
  const genericOnly = matched.length > 0 && matched.every((need) => GENERIC_NEEDS.has(need));
  const genericPenalty = genericOnly && needs.some((need) => !GENERIC_NEEDS.has(need)) ? 12 : 0;
  return Math.min(40, weight) + primaryBonus - genericPenalty;
}

