import { AtomicProjectStore } from "../src/server/store/atomic-project-store.ts";
import { approveProduct, approveSection, reviseSection } from "../src/server/workflow/transitions.ts";
import { createProject, type Project } from "../src/server/workflow/model.ts";
import { WorkflowService } from "../src/server/workflow/service.ts";

const engine = async () => ({
  available: true,
  serverVersion: "2.0.32",
  model: "opencode/deepseek-v4.1-flash-free" as const,
  modelAvailable: true,
  limitation: null,
});

const headers = { "content-type": "application/json", "x-ub-session-token": "test-token" };

function withProduct(idea: string, approve = true): Project {
  let project = createProject("/workspace");
  project.product = { status: "PROPOSED", proposal: idea, openQuestions: [] };
  if (approve) project = approveProduct(project);
  return project;
}

function approveThrough(project: Project, lastSectionId: string): Project {
  let next = project;
  for (const section of project.sections) {
    const current = next.sections.find((item) => item.id === section.id)!;
    next = reviseSection(next, section.id, `${section.title} approved for the test.`);
    const drafted = next.sections.find((item) => item.id === section.id)!;
    next = approveSection(next, section.id, drafted.version, drafted.hash);
    assert.equal(next.sections.find((item) => item.id === section.id)?.status, "APPROVED");
    if (section.id === lastSectionId) break;
    assert.ok(current);
  }
  return next;
}

async function workshop(project?: Project) {
  const directory = await mkdtemp(join(tmpdir(), "ub-recommendations-"));
  const store = new AtomicProjectStore(join(directory, "project.json"));
  const seeded = project ?? withProduct("A campus lost-and-found web app with a SQLite database.");
  await store.initialize(seeded);
  const workflow = new WorkflowService(store);
  const recommendations = new RecommendationService(workflow);
  const app = createApp(engine, { service: workflow, sessionToken: "test-token", recommendations });
  return { app, store, workflow, recommendations };
}

const profileCases: Array<{ name: string; idea: string; constraints?: RecommendationInput["constraints"]; top: string; includes?: string[] }> = [
  {
    name: "local web app",
    idea: "A campus lost-and-found web app with a SQLite database and accessibility checks for a 24 hour deadline.",
    top: "sqlite",
    includes: ["axe-core"],
  },
  {
    name: "tabular prediction",
    idea: "Predict house prices from a CSV using a tabular model and a small dataset.",
    top: "tabpfn",
  },
  {
    name: "voice assistant",
    idea: "A voice assistant that reads documents aloud and transcribes speech.",
    top: "elevenlabs",
  },
  {
    name: "durable workflow",
    idea: "A durable workflow for invoice retries, background jobs, and long-running orchestration.",
    top: "temporal",
  },
  {
    name: "remote auth and vector search",
    idea: "An AI app with login, authentication, a remote MongoDB database, vector search, and a public URL.",
    top: "mongodb-atlas",
    includes: ["auth0-ai-agents"],
  },
  {
    name: "hardware monitor",
    idea: "An Arduino garden sensor with time-series charts and offline data.",
    constraints: { noSpend: false },
    top: "arduino",
    includes: ["tiger-data", "sqlite"],
  },
];

for (const profile of profileCases) {
  test(`table profile: ${profile.name}`, () => {
    const result = recommend({ idea: profile.idea, constraints: profile.constraints });
    assert.equal(result.recommendations[0]?.tool.id, profile.top, JSON.stringify(result.recommendations.map((item) => item.tool.id)));
    for (const expected of profile.includes ?? []) {
      assert.ok(result.recommendations.some((item) => item.tool.id === expected), `expected ${expected}`);
    }
    assert.ok(result.recommendations.length <= 5);
    assert.equal(result.catalog.version.length > 0, true);
    assert.equal(result.catalog.verifiedOn, TOOL_CATALOG_VERIFIED_ON);
  });
}

test("local-only excludes hosted-only services", () => {
  const result = recommend({
    idea: "An AI app with login, authentication, a remote MongoDB database, vector search, and a public URL.",
    constraints: { localOnly: true },
  });
  for (const toolId of ["mongodb-atlas", "auth0-ai-agents", "render", "serpapi"]) {
    assert.equal(result.recommendations.some((item) => item.tool.id === toolId), false, toolId);
  }
  assert.ok(result.recommendations.every((item) => item.tool.setupMode !== "hosted" || item.tool.selfHost === "yes"));
  assert.match(result.warnings.join(" "), /Local-only is on/);
});

test("open-source-only excludes proprietary tools and keeps mixed licences visible", () => {
  const result = recommend({
    idea: "An AI app with voice, authentication, a remote database, and vector search.",
    constraints: { openSourceOnly: true },
  });
  assert.equal(result.recommendations.some((item) => item.tool.openness === "proprietary"), false);
  const mixed = result.recommendations.filter((item) => item.tool.openness === "mixed");
  for (const item of mixed) {
    assert.match(item.whyNot.join(" "), /Mixed licensing/);
  }
});

test("no-spending never presents promotional credit as permanent free usage", () => {
  const result = recommend({
    idea: "Fine-tune a model with LoRA on a custom dataset.",
    constraints: { noSpend: true },
  });
  assert.notEqual(result.recommendations[0]?.tool.id, "tinker");
  const tinker = result.recommendations.find((item) => item.tool.id === "tinker");
  if (tinker) {
    assert.match(tinker.whyNot.join(" "), /Promotional credit or trial access is temporary/);
    assert.equal(tinker.tool.cost.permanentFree, false);
  }
  assert.match(result.warnings.join(" "), /trial and promotional credit is not treated as permanent free usage/);
});

test("hardware-unavailable excludes Arduino", () => {
  const result = recommend({
    idea: "An Arduino garden sensor with time-series charts.",
    constraints: { noSpend: false, hardwareAvailable: "none" },
  });
  assert.equal(result.recommendations.some((item) => item.tool.id === "arduino"), false);
  assert.match(explainExclusion({ idea: "An Arduino garden sensor.", constraints: { hardwareAvailable: "none" } }, "arduino").join(" "), /Hardware is unavailable/);
});

test("stale catalog data is flagged with the verification policy", () => {
  const fresh = recommend({ idea: "A web app with a SQLite database." });
  assert.equal(fresh.catalog.stale, false);
  const stale = recommend({ idea: "A web app with a SQLite database.", now: "2027-10-31" });
  assert.equal(stale.catalog.stale, true);
  assert.ok(stale.catalog.staleToolIds.length > 0);
  assert.match(stale.warnings.join(" "), /Catalog data is stale/);
  assert.ok(stale.recommendations.every((item) => item.stale));
});

test("conflicting local and remote data choices resolve deterministically", () => {
  const first = recommend({
    idea: "An app with a remote MongoDB database and a local SQLite database.",
    constraints: { localOnly: true, noSpend: true },
  });
  const second = recommend({
    idea: "An app with a remote MongoDB database and a local SQLite database.",
    constraints: { localOnly: true, noSpend: true },
  });
  assert.deepEqual(first.recommendations.map((item) => item.tool.id), second.recommendations.map((item) => item.tool.id));
  assert.equal(first.recommendations.some((item) => item.tool.id === "mongodb-atlas"), false);
  assert.equal(first.recommendations[0]?.tool.id, "sqlite");
});

test("stable ordering is deterministic across identical calls", () => {
  const input: RecommendationInput = {
    idea: "An AI assistant with voice and a local database.",
    constraints: { noSpend: false },
  };
  const first = recommend(input);
  const second = recommend(input);
  assert.deepEqual(first, second);
  assert.deepEqual(first.recommendations.map((item) => item.tool.id), second.recommendations.map((item) => item.tool.id));
});

test("recommendations do not invent prices or unlimited/free-forever claims", () => {
  const result = recommend({
    idea: "A voice app with login and a remote database.",
    constraints: { noSpend: true },
  });
  for (const item of result.recommendations) {
    const text = [...item.why, ...item.whyNot, ...item.limitations].join(" ");
    assert.doesNotMatch(text, /\$\s?\d/);
    assert.doesNotMatch(text, /\bunlimited\b|\bfree forever\b|\bguaranteed\b/i);
    assert.doesNotMatch(item.tool.challengeRelevance, /\bwinner\b|\baward\b|\bprize\b/i);
  }
});

test("a tool is not recommended only because it sponsors a challenge", () => {
  const result = recommend({ idea: "A simple to-do list with no AI, no database, and no deployment." });
  for (const toolId of ["tinker", "digitalocean", "backboard", "ultramarine", "tech-domain"]) {
    assert.equal(result.recommendations.some((item) => item.tool.id === toolId), false, toolId);
  }
  assert.ok(result.recommendations.every((item) => item.matchedNeeds.length > 0));
});

test("OpenCode-only projects are never advised to switch harnesses", () => {
  const result = recommend({
    idea: "Use OpenCode only for a local coding session history tool.",
    constraints: { localOnly: true, openSourceOnly: true, noSpend: true, existingStack: ["opencode"] },
  });
  assert.equal(result.recommendations.some((item) => item.tool.id === "github-copilot"), false);
  assert.equal(result.recommendations.some((item) => item.tool.harnessAlternative), false);
  assert.equal(result.baseline[0]?.tool.id, "opencode");
  assert.match(explainExclusion({ idea: "Use OpenCode only." }, "github-copilot").join(" "), /OpenCode is the only harness/);
});

test("catalog entries carry a source and verification date", () => {
  for (const tool of TOOL_CATALOG) {
    assert.ok(tool.sources.length > 0, tool.id);
    assert.ok(tool.sources.every((source) => source.url.startsWith("https://")), tool.id);
    assert.match(tool.lastVerified, /^\d{4}-\d{2}-\d{2}$/, tool.id);
    assert.ok(tool.cost.limits.length > 0, tool.id);
    if (tool.status === "promo-only") {
      assert.equal(tool.cost.promotional || tool.cost.kind === "trial", true, tool.id);
    }
    if (tool.id === "github-copilot") assert.equal(tool.status, "excluded");
  }
  assert.ok(catalogTool("opencode"));
  assert.ok(catalogTool("render"));
  assert.ok(catalogTool("tiger-data"));
  assert.ok(catalogTool("browserbase-stagehand"));
});

test("safe serialization round-trips the complete result", () => {
  const result = recommend({
    idea: "A web app with a SQLite database, accessibility checks, and a public URL.",
    constraints: { noSpend: true, localOnly: false, deadlineHours: 24 },
  });
  const roundTrip = JSON.parse(JSON.stringify(result)) as typeof result;
  assert.deepEqual(roundTrip, result);
  assert.equal(typeof (result as unknown as { install?: unknown }).install, "undefined");
  assert.equal(typeof (result as unknown as { deploy?: unknown }).deploy, "undefined");
});

test("adding before the Tools section is approved is rejected without side effects", async () => {
  const project = withProduct("A campus lost-and-found web app with a SQLite database.");
  const { app, store } = await workshop(project);
  const before = (await store.load()).state;
  const response = await app.request("/api/recommendations/sqlite/decisions", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "too-early", expectedRevision: before.revision, status: "ADDED" }),
  });
  assert.equal(response.status, 409);
  const after = (await store.load()).state;
  assert.equal(after.toolDecisions.length, 0);
  assert.equal(after.operations.length, before.operations.length);
});

test("approve, defer, and reject decisions persist without performing an external action", async () => {
  const project = approveThrough(withProduct("A campus lost-and-found web app with a SQLite database."), "tools");
  const { app, store } = await workshop(project);
  const loaded = (await store.load()).state;
  const operationsBefore = loaded.operations.length;

  const add = await app.request("/api/recommendations/sqlite/decisions", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "add-sqlite", expectedRevision: loaded.revision, status: "ADDED" }),
  });
  assert.equal(add.status, 200);
  const added = await add.json();
  assert.equal(added.project.toolDecisions.find((item: { toolId: string }) => item.toolId === "sqlite").status, "ADDED");
  assert.equal(added.project.operations.length, operationsBefore);
  assert.equal(added.recommendations.selected[0].tool.id, "sqlite");

  const defer = await app.request("/api/recommendations/axe-core/decisions", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "defer-axe", expectedRevision: added.project.revision, status: "DEFERRED" }),
  });
  assert.equal(defer.status, 200);
  const deferred = await defer.json();
  assert.equal(deferred.project.toolDecisions.find((item: { toolId: string }) => item.toolId === "axe-core").status, "DEFERRED");

  const reject = await app.request("/api/recommendations/gemma/decisions", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "reject-gemma", expectedRevision: deferred.project.revision, status: "REJECTED" }),
  });
  assert.equal(reject.status, 200);
  const rejected = await reject.json();
  assert.equal(rejected.project.toolDecisions.find((item: { toolId: string }) => item.toolId === "gemma").status, "REJECTED");

  const repeat = await app.request("/api/recommendations/sqlite/decisions", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "add-sqlite", expectedRevision: loaded.revision, status: "ADDED" }),
  });
  assert.equal(repeat.status, 200);
  assert.equal((await repeat.json()).duplicate, true);

  const exported = await (await app.request("/api/export")).json();
  assert.equal(exported.selectedTools.some((item: { toolId: string }) => item.toolId === "sqlite"), true);
  assert.match(exported.limitation, /does not install/);
  assert.equal((await store.load()).state.toolDecisions.filter((item) => item.toolId === "sqlite").length, 1);
});

