test("explicit filters persist and change the recommendation set", async () => {
  const project = withProduct("An AI app with a remote MongoDB database, login, and a public URL.");
  const { app, store } = await workshop(project);
  const loaded = (await store.load()).state;
  assert.ok(loaded.recommendations ?? true);
  const response = await app.request("/api/recommendations/context", {
    method: "POST",
    headers,
    body: JSON.stringify({
      actionId: "filters",
      expectedRevision: loaded.revision,
      needs: ["local-database"],
      constraints: {
        noSpend: true,
        localOnly: true,
        openSourceOnly: false,
        privacySensitive: false,
        deadlineHours: 24,
        hardwareAvailable: "unknown",
        existingStack: [],
      },
    }),
  });
  assert.equal(response.status, 200);
  const body = await response.json();
  assert.deepEqual(body.project.recommendationContext.needs, ["local-database"]);
  assert.equal(body.project.recommendationContext.constraints.localOnly, true);
  assert.ok(body.recommendations.recommendations.every((item: { tool: { id: string } }) => item.tool.id !== "mongodb-atlas"));
  assert.equal(body.recommendations.idea.needs[0], "local-database");
});

